
const STORAGE='tribunal_100casos_v2';const AREAS=['Todas','Penal','Família','Cível','Trabalhista','Consumidor','Empresarial','Previdenciário','Administrativo'];
const DEFAULT={lawyer:'Dra. Aurora Silva',cash:185420,reputation:50,day:1,category:'Todas',difficulty:'Todas',query:'',view:'inicio',tab:'resumo',selected:null,careerArea:['Penal','Família'],cases:{},logs:[],casesPlayed:0};
let s={...DEFAULT};try{let saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');s={...DEFAULT,...saved,cases:saved.cases||{}}}catch(e){}
const $=x=>document.getElementById(x);const es=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n||0);const get=id=>CASES.find(c=>c.id===id);const iCur=()=>get(s.selected);const pCur=()=>s.cases[s.selected];
function store(){try{localStorage.setItem(STORAGE,JSON.stringify(s))}catch(e){toast('Armazenamento cheio; exporte o progresso.')}}
function refresh(scroll=false){store();render();if(scroll)window.scrollTo({top:0,behavior:'smooth'})}
function toast(msg){let d=document.createElement('div');d.className='toast';d.textContent=msg;document.body.appendChild(d);setTimeout(()=>d.remove(),3300)}
function nav(view){s.view=view;refresh(true)}
function selected(id,tab='resumo'){s.selected=id;s.tab=tab;s.view='dossie';refresh(true)}
function caseProgress(c){return s.cases[c.id]}
function initialProcess(c){return {budget:{income1:78000,income2:9300,entries:[],receipts:[{id:'R-ESC',title:'Matrícula e mensalidade escolar',amount:3350,source:'Boleto quitado no sistema fictício'},{id:'R-SAU',title:'Plano de saúde da criança',amount:1280,source:'Extrato do plano de saúde ficcional'},{id:'R-TRA',title:'Transporte escolar',amount:610,source:'Recibo de transportadora do universo do jogo'}]},phase:0,status:'Ativo',selected:c.evidence.filter(e=>e.initial).map(e=>e.id),attached:[],challenged:[],investigations:0,history:[{day:s.day,text:'Pasta aberta para triagem, conferência de perfil e negociação. Atuação ainda não aceita.'}],transcript:[],documents:[],messages:[],petition:'',hearingActions:[],witnessQuestionCount:0,revision:[],fees:0,decision:null,uploaded:[]}}
function doc(p,c,title,content,type='Peça'){p.documents.unshift({id:'D'+Date.now()+Math.round(Math.random()*1e6),title,content,type,day:s.day,caseId:c.id})}
function accept(id){let c=get(id);if(!c)return;if(!s.cases[id]){let p=initialProcess(c);s.cases[id]=p;s.casesPlayed++;let base=`ESCRITÓRIO · RELATÓRIO DE ATENDIMENTO\n${c.id} · ${c.number}\n${c.title} / ${c.kind}\nAssistido: ${c.client}\nContraparte: ${c.opponent}\nVara sugerida: ${c.venue}\n\nVERSÃO DO ASSISTIDO\n${c.claim}\n\nVERSÃO ADVERSA\n${c.opponentClaim}\n\nQUESTÃO A APURAR\n${c.twist}\n\nREGRA: fatos narrados não equivalem a fatos provados.`;doc(p,c,'Relatório preliminar de atendimento',base,'Relatório');doc(p,c,'Procuração simulada',`MINUTA DE PROCURAÇÃO — SUJEITA À CONTRATAÇÃO\nOutorgante: ${c.client}\nAdvogada: ${s.lawyer}\nAutos: ${c.number}\nObjeto: representação na causa ${c.kind}.\nSem validade jurídica.`, 'Procuração');toast('Pasta aberta para atendimento e contratação.')}selected(id)}
function recordCaseHistory(p,text){p.history.unshift({day:s.day,text});s.logs.unshift({day:s.day,caseId:s.selected,text});s.logs=s.logs.slice(0,130)}
function selectCategory(x){s.category=x;s.view='casos';refresh()}
function changeDifficulty(x){s.difficulty=x;refresh()}
function searchQuery(x){let cursor=$('caseSearch')?.selectionStart??x.length;s.query=x;refresh();let el=$('caseSearch');if(el){el.focus();el.setSelectionRange(cursor,cursor)}}
function randCase(){let ar=CASES.filter(c=>(s.category==='Todas'||c.area===s.category)&&!s.cases[c.id]);if(!ar.length)ar=CASES.filter(c=>s.category==='Todas'||c.area===s.category);if(ar.length)accept(ar[Math.floor(Math.random()*ar.length)].id)}
function stepDay(){s.day++;historyLocal('Avanço do calendário em um dia fictício.');refresh();toast('O calendário avançou. Consulte agenda e prazos fictícios.')}
function historyLocal(text){s.logs.unshift({day:s.day,caseId:'GERAL',text})}
function revealNext(){let c=iCur(),p=pCur();if(!p)return;let pending=c.evidence.filter(e=>!p.selected.includes(e.id));if(!pending.length){toast('Todas as provas previstas neste dossiê já foram obtidas.');return}let e=pending[0];p.selected.push(e.id);p.investigations++;s.cash-=180;recordCaseHistory(p,'Diligência concluída: '+e.title+' · custo fictício de R$ 180.');doc(p,c,'Juntada de diligência — '+e.title,evidencePaper(c,e),'Diligência');refresh();toast('Nova prova obtida: '+e.title)}
function evidencePaper(c,e){return `DOCUMENTO FICCIONAL DE JOGO\n${c.id} · ${c.number}\nREGISTRO: ${e.id}\nTÍTULO: ${e.title}\nORIGEM DECLARADA: ${e.source}\nTIPO: ${e.type}\nDATA: ${e.obtained}\nSITUAÇÃO: ${e.status}\nINTEGRIDADE: ${e.integrity}\n\nCONTEÚDO:\n${e.body}\n\nLIMITAÇÃO:\n${e.caution}\n\nRegistro do universo ficcional. Não constitui prova judicial real.`}
function attachEv(id){let p=pCur();if(!p.selected.includes(id))return;let k=p.attached.indexOf(id);if(k>=0)p.attached.splice(k,1);else p.attached.push(id);recordCaseHistory(p,(k>=0?'Desvinculada':'Juntada')+' prova '+id);refresh()}
function contestEv(id){let p=pCur();if(!p.selected.includes(id))return;if(!p.challenged.includes(id)){p.challenged.push(id);recordCaseHistory(p,'Impugnação e pedido de verificação de autenticidade: '+id)}refresh()}
function makePetition(){let c=iCur(),p=pCur(),value=$('petition')?.value.trim()||'';if(value.length<80){toast('A peça exige argumentação de pelo menos 80 caracteres.');return}p.petition=value;p.phase=Math.max(1,p.phase);recordCaseHistory(p,'Peça processual protocolada e registrada nos autos simulados.');doc(p,c,'Manifestação da defesa',`AO JUÍZO COMPETENTE (SIMULAÇÃO)\nPROCESSO ${c.number}\nASSISTIDO: ${c.client}\n\n${value}\n\nRequer-se apreciação fundamentada, considerando os documentos e o contraditório.\n\n${s.lawyer}\nDOCUMENTO FICTÍCIO.`, 'Petição');refresh();toast('Manifestação incluída nos autos.')}
function documentText(id){let p=pCur();return p?.documents.find(d=>d.id===id)}
function readDoc(id){let d=documentText(id);if(!d)return;document.body.insertAdjacentHTML('beforeend',`<div class="modalbg" id="docModal"><div class="modal"><div class="rows between"><div><div class="eyebrow">${es(d.type)}</div><h3>${es(d.title)}</h3></div><button class="btn sm" onclick="closeModal()">Fechar ✕</button></div><pre class="paper">${es(d.content)}</pre><button class="btn dark" onclick="exportDoc('${es(d.id)}')">↓ Exportar TXT</button></div></div>`)}
function closeModal(){$('docModal')?.remove()}
function download(text,name,mime='text/plain;charset=utf-8'){let blob=new Blob([text],{type:mime});let u=URL.createObjectURL(blob);let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function exportDoc(id){let d=documentText(id);if(d)download(d.content,d.title.replace(/[^\p{L}\p{N}-]/gu,'_')+'.txt')}
function exportCase(){let c=iCur(),p=pCur();if(c&&p)download(JSON.stringify({case:c,progress:p},null,2),c.id+'_autos.json','application/json')}
function uploadEvidence(){let c=iCur(),p=pCur(),f=$('uploadFile')?.files?.[0];if(!f)return toast('Selecione um documento.');if(f.size>1500000)return toast('Máximo de 1,5 MB por arquivo.');let reader=new FileReader();reader.onload=()=>{let text='';if(f.type.startsWith('text/')||/\.txt$|\.csv$|\.json$/i.test(f.name))text=String(reader.result).slice(0,60000);let u={name:f.name,size:f.size,mime:f.type,day:s.day,verified:false,content:text};p.uploaded.push(u);doc(p,c,'Anexo importado — '+f.name,`IMPORTADO PELO JOGADOR · NÃO VERIFICADO\nNome: ${f.name}\nTipo: ${f.type}\nTamanho: ${f.size} bytes\n\n${text||'Conteúdo binário não incorporado ao texto do simulador; este registro documenta apenas a seleção do arquivo.'}\n\nImportação não atesta autoria ou autenticidade.`, 'Anexo não verificado');recordCaseHistory(p,'Arquivo apresentado, sem verificação: '+f.name);refresh();toast('Anexo marcado como NÃO VERIFICADO.')};reader.readAsText(f)}
function statusGemini(){fetch('/api/status',{signal:AbortSignal.timeout(2700)}).then(r=>r.json()).then(x=>{let el=$('aistatus');if(el)el.textContent=x.gemini?'Gemini conectado · respostas de IA disponíveis':'Modo local ativo · adicione GEMINI_API_KEY no Netlify'}).catch(()=>{let el=$('aistatus');if(el)el.textContent='Modo local · abra pelo endereço publicado no Netlify para usar o Gemini'})}
function localWitness(c,w,q,p){let k=q.toLowerCase();if(/ameaç|medo|sentiu|motivo|interesse|benefício/.test(k))return `Meu interesse neste processo é ${w.interest.toLowerCase()}. Vou responder dentro do que conheço: ${w.statement}`;
 if(/hora|quando|tempo|data|cronologia|dia/.test(k))return `O registro disponível é de ${c.date}, mas não tenho certeza de todos os horários. Posso explicar apenas o que presenciei e o que consta no meu depoimento.`;
 if(/prova|document|laudo|vídeo|vídeo|filmagem|foto|extrato|contrato|perícia|mensag/.test(k))return `${w.role==='Responsável pelo documento'?'Eu posso explicar o método usado, não garantir o fato final.':'Preciso confrontar o registro original e o contexto.'} Meu relato é: ${w.statement}`;
 if(/contradi|ment|diverg|inconsist|explica/.test(k))return `Aceito que uma divergência precisa ser examinada com as provas e com cuidado. ${w.statement}`;
 if(/onde|local|presen|viu|testemunh/.test(k))return `Não afirmo o que não presenciei. Meu relato formal é: ${w.statement}`;
 return `${w.statement} Sobre “${q.slice(0,95)}”, não tenho outro fato registrado além do que consta neste dossiê.`;
}
async function chat(){let c=iCur(),p=pCur();if(!p)return;let wid=$('personSel')?.value||c.witnesses[0].id, q=$('ask')?.value.trim();if(!q)return;let w=c.witnesses.find(x=>x.id===wid);p.messages.push({role:'player',who:s.lawyer,to:w.name,text:q,day:s.day});p.witnessQuestionCount++;let answer='';try{let r=await fetch('/api/character',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({case:c,character:w,question:q,history:p.messages.slice(-12),knownEvidenceIds:p.selected})});if(!r.ok)throw new Error('Offline');let j=await r.json();answer=String(j.reply||'').slice(0,2600);if(!answer.trim())throw new Error('Resposta vazia')}catch(e){answer=localWitness(c,w,q,p);toast('Gemini não respondeu: diálogo local utilizado, sem cobrança.')}
 p.messages.push({role:'npc',who:w.name,text:answer,day:s.day});recordCaseHistory(p,`Oitiva informal de ${w.name}: uma pergunta registrada.`);doc(p,c,`Termo de entrevista · ${w.name}`,`TERMO FICTÍCIO DE ENTREVISTA\n${s.lawyer}: ${q}\n${w.name}: ${answer}\n\nNão equivale a depoimento judicial.`,'Entrevista');refresh()}
function startHearing(){let p=pCur(),c=iCur();if(!p)return;if(!p.petition||p.attached.length<2){toast('Para abrir audiência, protocole uma peça e junte pelo menos duas provas.');return}p.phase=Math.max(2,p.phase);p.transcript.push({who:'Serventia',text:`Audiência fictícia aberta nos autos ${c.number}. Presentes defesa, parte contrária e autoridade judicial.`});p.transcript.push({who:'Parte contrária',text:c.opponentClaim});recordCaseHistory(p,'Audiência iniciada; contraditório e ata disponíveis.');refresh()}
function hearingAction(a){let p=pCur(),c=iCur();if(!p||p.phase<2)return;let responses={contraditorio:'Defesa requer que a parte contrária se manifeste sobre a prova documental e sua origem.',pericia:'Defesa pede complementação técnica sobre lacuna e autenticidade documental.',acordo:'Defesa propõe composição consensual quando juridicamente cabível, sem impor acordo.',depoimento:'Defesa solicita oitiva de testemunha pertinente e questionamento sem indução.',impugnacao:'Defesa impugna a leitura isolada de uma prova e requer exame do registro integral.'};let judges={contraditorio:'O pedido de contraditório é registrado. Concedida oportunidade de manifestação.',pericia:'A utilidade da perícia será apreciada conforme objeto da causa. Decisão provisória: deferida parcialmente.',acordo:c.area==='Penal'?'A conciliação não substitui o procedimento penal aplicável; requerimento não acolhido nesta forma.':'A proposta poderá ser encaminhada às partes, sem obrigar aceitação.',depoimento:'O depoimento foi solicitado; a autoridade observará os limites e o rito aplicáveis.',impugnacao:'A impugnação fica consignada e será examinada em conjunto com os demais elementos.'};
 p.hearingActions.push(a);p.transcript.push({who:s.lawyer,text:responses[a]});p.transcript.push({who:'Juízo',text:judges[a]});recordCaseHistory(p,'Audiência: '+a);refresh()}
function decision(){let p=pCur(),c=iCur();if(!p||p.phase<2)return;let evidence=p.attached.map(id=>c.evidence.find(e=>e.id===id)).filter(Boolean);let w=evidence.reduce((x,e)=>x+e.weight,0);let score=3+w+(p.petition.length>200?2:0)+Math.min(3,p.hearingActions.filter(x=>x==='impugnacao'||x==='contraditorio'||x==='pericia').length)+(p.witnessQuestionCount>0?1:0)-Math.max(0,c.difficulty-2);let result=score>=15?'Procedência / tese defensiva acolhida em parte relevante':score>=9?'Acolhimento parcial, com diligências ou ajustes':'Pedidos rejeitados ou tese insuficientemente demonstrada';
 let summary=`DECISÃO SIMULADA\nProcesso: ${c.number}\nAssunto: ${c.kind}\nConclusão: ${result}.\n\nFUNDAMENTAÇÃO (JOGO)\nForam examinados ${evidence.length} documentos formalmente juntados, ${p.witnessQuestionCount} perguntas em entrevistas e ${p.hearingActions.length} requerimentos de audiência. ${evidence.some(e=>e.weight<0)?'Há elementos contrários à tese que não podem ser ignorados.':''} A controvérsia principal permanece vinculada à seguinte questão: ${c.twist} Provas importadas sem verificação não foram tratadas como autênticas.\n\nEsta decisão é uma simulação didática, não sentença nem parecer profissional.\nPontuação do motor: ${score}.`;
 p.decision={result,score,text:summary,day:s.day};p.phase=3;p.status='Decidido';doc(p,c,'Decisão fundamentada simulada',summary,'Decisão');doc(p,c,'Ata de audiência',minutesText(c,p),'Ata');recordCaseHistory(p,'Decisão proferida: '+result);let honor=1500+c.difficulty*500;s.cash+=honor;p.fees+=honor;s.reputation=Math.min(100,Math.max(0,s.reputation+(score>=9?2:-1)));refresh();toast('Decisão registrada com ata e fundamentação.')}
function minutesText(c,p){return `ATA DE AUDIÊNCIA · TRIBUNAL (FICTÍCIA)\nProcesso: ${c.number}\nParte assistida: ${c.client}\nRepresentante: ${s.lawyer}\nDia da carreira: ${s.day}\n\n${p.transcript.map(t=>t.who+': '+t.text).join('\n\n')}\n\nDocumentos juntados: ${p.attached.join(', ')||'Nenhum'}\nResultado: ${p.decision?.result||'Pendente'}\n\nDocumento sem validade judicial.`}
function revision(){let p=pCur(),c=iCur();if(!p?.decision)return toast('O caso ainda não tem decisão.');let reason=$('revisionText')?.value.trim()||'';if(reason.length<45)return toast('Descreva os fundamentos do pedido (mín. 45 caracteres).');p.revision.push({day:s.day,text:reason,status:'Recebido para exame simulado'});recordCaseHistory(p,'Revisão/recurso requerido: verificar cabimento e prazo no rito do processo.');doc(p,c,'Pedido de reexame',`REQUERIMENTO DE REEXAME · FICTÍCIO\nProcesso ${c.number}\nFundamentação: ${reason}\nA admissibilidade depende do rito, do ato e dos prazos aplicáveis.`, 'Pedido de reexame');refresh();toast('Pedido registrado; não altera automaticamente a decisão.')}
function addExpense(){let p=pCur(),c=iCur();if(!p||c.area!=='Família')return;let b=p.budget,description=$('expName')?.value.trim(),amount=Number($('expValue')?.value),share=Number($('expShare')?.value),proof=$('expProof')?.value||'';if(!description||!Number.isFinite(amount)||amount<=0||amount>500000||!Number.isFinite(share)||share<1||share>100)return toast('Informe descrição, valor e rateio entre 1% e 100%.');let receipt=b.receipts.find(x=>x.id===proof);if(receipt&&b.entries.some(x=>x.proof===proof))return toast('O mesmo recibo já foi usado em outro lançamento. Evite duplicação.');if(receipt&&Math.abs(receipt.amount-amount)>1)return toast('O valor do comprovante precisa coincidir com o valor lançado.');let value=Math.round(amount*share)/100;b.entries.push({description,amount,share,proof,monthly:value,verified:!!receipt,day:s.day});let message='Despesa '+description+' · '+fmt(value)+' atribuída à criança ('+share+'%) · '+(receipt?'com comprovante interno associado':'alegada sem comprovante');recordCaseHistory(p,message);doc(p,c,'Demonstrativo de despesa — '+description,`REGISTRO FICTÍCIO DE DESPESA\nProcesso ${c.number}\nItem: ${description}\nValor total: ${fmt(amount)}\nRateio para criança: ${share}%\nParcela atribuível: ${fmt(value)}\nComprovante: ${receipt?receipt.title+' / '+receipt.source:'NÃO APRESENTADO'}\nO recibo não demonstra, isoladamente, dever exclusivo de uma parte.`, 'Despesa infantil');refresh();toast('Despesa adicionada ao dossiê.');}
function updateIncome(kind,val){let p=pCur();if(!p)return;let x=Number(val);if(!Number.isFinite(x)||x<0||x>5000000)return;p.budget[kind]=x;store()}
function familyBudget(c,p){let b=p.budget||(p.budget={income1:78000,income2:9300,entries:[],receipts:[]});let verified=b.entries.filter(x=>x.verified).reduce((a,x)=>a+x.monthly,0),claimed=b.entries.filter(x=>!x.verified).reduce((a,x)=>a+x.monthly,0),total=verified+claimed,ratio=b.income1+b.income2>0?b.income1/(b.income1+b.income2):0;return `<div class="cols"><div class="panel"><div class="eyebrow">FAMÍLIA · NECESSIDADE E POSSIBILIDADE</div><h2>Demonstrativo de custos infantis</h2><p>A pensão não é automaticamente 30% da renda. O cálculo abaixo é um <b>cenário didático</b>, não decisão judicial: considere necessidades reais, capacidade de ambos os responsáveis, documentação e especificidades do caso.</p><div class="field"><label>Renda mensal demonstrada/alegada do responsável 1 (R$)</label><input type="number" min="0" value="${b.income1}" onchange="updateIncome('income1',this.value);refresh()"></div><div class="field"><label>Renda mensal demonstrada/alegada do responsável 2 (R$)</label><input type="number" min="0" value="${b.income2}" onchange="updateIncome('income2',this.value);refresh()"></div><hr class="sepline"><h3>Registrar despesa</h3><div class="field"><label>Descrição</label><input id="expName" placeholder="Ex.: mensalidade escolar"></div><div class="field"><label>Valor total do pagamento (R$)</label><input id="expValue" type="number" min="1" placeholder="Ex.: 3350"></div><div class="field"><label>Percentual destinado à criança (1–100%)</label><input id="expShare" type="number" value="100" min="1" max="100"></div><div class="field"><label>Comprovante interno correspondente (quando existente)</label><select id="expProof"><option value="">Nenhum: apenas despesa alegada</option>${b.receipts.map(x=>`<option value="${x.id}">${es(x.title)} — ${fmt(x.amount)}</option>`).join('')}</select></div><button class="btn primary" onclick="addExpense()">Incluir no dossiê e gerar documento</button></div><div class="panel"><h2>Análise de proporcionalidade</h2><div class="tiles" style="grid-template-columns:repeat(2,1fr)"><div class="tile"><strong>${fmt(verified)}</strong><small>Despesas com registro interno</small></div><div class="tile"><strong>${fmt(claimed)}</strong><small>Despesas alegadas</small></div><div class="tile"><strong>${fmt(total)}</strong><small>Custo infantil atribuído</small></div><div class="tile"><strong>${Math.round(ratio*100)}%</strong><small>Participação proporcional ilustrativa do responsável 1</small></div></div><div class="warning"><b>Referência proporcional ilustrativa:</b> ${fmt(total*ratio)} para o responsável 1, antes de apurar cuidado direto, despesas não documentadas, outras necessidades e obrigações. Não há modificação automática de pensão.</div><h3>Itens lançados</h3>${b.entries.map((e,idx)=>`<div class="docentry"><div><b>${es(e.description)}</b><div class="mini">${e.share}% do valor ${fmt(e.amount)} · ${e.verified?'Comprovante do universo fictício':'Não comprovado'}</div></div><b>${fmt(e.monthly)}</b></div>`).join('')||'<p class="muted">Registre gastos atribuíveis à criança. Não some integralmente despesas compartilhadas de toda a casa.</p>'}</div></div>`}
function goTab(t){s.tab=t;refresh()}
function dashboard(){let ongoing=Object.keys(s.cases).length;return `<div class="scene"><img class="scene-person" src="data:image/svg+xml;base64," alt="Advogada em ilustração 3D"><div class="scene-content"><div class="eyebrow">SIMULADOR JURÍDICO BRASILEIRO · EDIÇÃO 100 CASOS</div><h1>Uma carreira. Cem histórias. Nenhuma defesa automática.</h1><p>Gerencie processos, descubra provas e confronte depoimentos em um universo jurídico fictício com personagens 3D animados.</p><div class="rows scene-buttons"><button class="btn primary" onclick="nav('casos')">Explorar os 100 casos</button><button class="btn" onclick="randCase()">⚄ Sortear atendimento</button></div></div></div>
 <div class="tiles"><div class="tile"><strong>100</strong><small>Casos diferentes</small></div><div class="tile"><strong>1.000</strong><small>Elementos probatórios</small></div><div class="tile"><strong>400</strong><small>Personagens para ouvir</small></div><div class="tile"><strong>${ongoing}</strong><small>Casos do seu escritório</small></div></div>
 <div class="cols"><div class="panel"><div class="eyebrow">EM DESTAQUE</div><h2>${es(CASES[0].title)}</h2><div class="who"><img class="portrait" src="${CASES[0].cover}" alt="Personagem ilustrado"><div><b>${es(CASES[0].client)}</b><br><span class="tag red">Penal · alta repercussão</span><p class="mini">${es(CASES[0].twist)}</p></div></div><button class="btn dark" onclick="accept('${CASES[0].id}')">Abrir caso em destaque →</button></div><div class="panel"><div class="eyebrow">CENTRAL DO ESCRITÓRIO</div><h2>Seu expediente</h2><p>${es(s.lawyer)} · reputação ${s.reputation}/100 · dia ${s.day}.</p><p class="mini">Casos não dependem de sorte para vencer: o resultado considera os autos, mas ainda usa regras demonstrativas simplificadas.</p><div class="rows"><button class="btn" onclick="nav('processos')">Ver processos</button><button class="btn" onclick="nav('escritorio')">Gerenciar escritório</button></div></div></div>`}
function caseCard(c){let taken=!!s.cases[c.id];return `<article class="casecard"><div class="casephoto"><img loading="lazy" src="${c.cover}" alt="Personagem 3D ilustrado"><span class="caseid">${c.id} · ${es(c.area)}</span></div><div class="casebody"><div class="rows"><span class="tag ${c.difficulty>=4?'red':c.difficulty===3?'gold':'green'}">${es(c.complexity)}</span><span class="tag">${c.evidence.length} provas</span></div><h3>${es(c.title)}</h3><p>${es(c.claim)}</p><button class="btn ${taken?'dark':'primary'}" onclick="${taken?`selected('${c.id}')`:`accept('${c.id}')`}">${taken?'Reabrir autos':'Aceitar cliente →'}</button></div></article>`}
function casesPage(){let arr=CASES.filter(c=>(s.category==='Todas'||c.area===s.category)&&(s.difficulty==='Todas'||String(c.difficulty)===s.difficulty)&&(!s.query||`${c.id} ${c.area} ${c.title} ${c.kind} ${c.client}`.toLowerCase().includes(s.query.toLowerCase())));return `<div class="eyebrow">CATÁLOGO DE CLIENTES</div><h1>Casos da carreira</h1><p class="muted">Cada atendimento possui narrativa individual, 10 provas com origem e limites, 4 personagens, documentos e audiência.</p><div class="casetools">${AREAS.map(a=>`<button class="chip ${s.category===a?'active':''}" onclick="selectCategory('${a}')">${es(a)} ${a==='Todas'?'(100)':'('+CASES.filter(c=>c.area===a).length+')'}</button>`).join('')}</div><div class="searchline"><input id="caseSearch" class="search" placeholder="Pesquisar nome, tipo, cliente ou ID" value="${es(s.query)}" oninput="searchQuery(this.value)"><select class="search" onchange="changeDifficulty(this.value)"><option value="Todas">Todas as dificuldades</option>${[1,2,3,4,5].map(d=>`<option value="${d}" ${s.difficulty===String(d)?'selected':''}>Nível ${d}</option>`).join('')}</select><button class="btn primary" onclick="randCase()">⚄ Sortear</button></div><p class="mini">${arr.length} caso(s) no filtro · ${Object.keys(s.cases).length} admitido(s) no escritório</p><div class="casegrid">${arr.map(caseCard).join('')||'<p>Nenhum caso encontrado.</p>'}</div>`}
function caseHeader(c,p){return `<div class="eyebrow">PASTA PROCESSUAL · ${c.id}</div><div class="rows between"><div><h1>${es(c.title)}</h1><div class="rows"><span class="tag dark">${es(c.area)}</span><span class="tag gold">${es(c.kind)}</span><span class="tag">${es(c.number)}</span></div></div><button class="btn" onclick="nav('casos')">← Catálogo</button></div><div class="steps">${[['Triagem',0],['Instrução',1],['Audiência',2],['Decisão',3]].map(([t,n])=>`<span class="step ${p.phase===n?'active':p.phase>n?'done':''}">${n+1}. ${t}</span>`).join('')}</div><div class="tabs">${[['resumo','Visão geral'],['provas','Provas'],['testemunhas','Testemunhas'],['entrevista','Entrevistar'],...(c.area==='Família'?[['custos','Custos dos filhos']]:[]),['peticao','Peças'],['audiencia','Audiência'],['autos','Autos / ata'],['decisao','Decisão e recurso']].map(([x,v])=>`<button class="${s.tab===x?'active':''}" onclick="goTab('${x}')">${v}</button>`).join('')}</div>`}
function overview(c,p){return `<div class="cols"><div class="panel"><div class="eyebrow">RELATÓRIO PRELIMINAR</div><h2>${es(c.kind)}</h2><div class="dossier"><b>Versão do cliente</b><p>${es(c.claim)}</p></div><div class="dossier"><b>Versão adversa</b><p>${es(c.opponentClaim)}</p></div><div class="warning"><b>Controvérsia central:</b> ${es(c.twist)}</div><div class="rows"><span class="tag">Dificuldade ${c.difficulty}/5</span><span class="tag">${es(c.venue)}</span></div></div><div class="panel"><div class="eyebrow">PARTICIPANTES DO PROCESSO</div><div class="who"><img class="portrait" src="${c.cover}" alt="Personagem 3D"><div><h3>${es(c.client)}</h3><span class="tag green">Cliente assistido</span><p class="mini">Parte contrária: ${es(c.opponent)}</p></div></div><hr class="sepline"><h3>Estratégia preliminar</h3><p>${es(c.legalNote)}</p><p class="mini"><b>Base normativa indicativa:</b> ${es(c.law)}. Conferir lei vigente e procedimento específico.</p><button class="btn dark" onclick="goTab('provas')">Examinar provas</button></div></div><div class="panel"><h3>Linha do tempo do processo</h3>${p.history.map(x=>`<div class="logentry"><small class="smallcaps">DIA ${x.day}</small> · ${es(x.text)}</div>`).join('')}</div>`}
function evidenceSymbol(e){return ({Documento:'▤',Termo:'✎','Linha do tempo':'◷',Recibo:'▣',Laudo:'♧',Mensagem:'✉','Registro externo':'▥',Depoimento:'❝',Mídia:'▣',Parecer:'§'})[e.type]||'▤'}
function evidencePage(c,p){return `<div class="panel"><div class="rows between"><div><div class="eyebrow">CENTRAL DE PROVAS</div><h2>Vestígios, documentos e confronto</h2><p class="muted">${p.selected.length}/${c.evidence.length} disponíveis · ${p.attached.length} juntados · ${p.challenged.length} impugnados.</p></div><button class="btn primary" onclick="revealNext()">✦ Realizar diligência — R$ 180</button></div><p class="warning">Provas contundentes podem favorecer ou prejudicar seu cliente. Documentos trazidos pelo jogador são identificados como não verificados e não viram fatos do caso automaticamente.</p>${c.evidence.map(e=>{let yes=p.selected.includes(e.id),added=p.attached.includes(e.id),cont=p.challenged.includes(e.id);return `<div class="evidence"><div class="evhead"><div class="evtype">${evidenceSymbol(e)}</div><div style="flex:1"><div class="rows between"><h4>${es(e.title)}</h4><span class="tag ${yes?'green':'red'}">${yes?'Disponível':'A obter'}</span></div><div class="mini">${e.id} · ${es(e.type)} · ${es(e.source)}</div>${yes?`<details><summary>Examinar documento completo ▾</summary><div class="paper"><div class="paperhead">${es(e.id)} · REGISTRO DO UNIVERSO FICTÍCIO</div><b>Conteúdo</b>\n${es(e.body)}\n\n<b>Limite de interpretação</b>\n${es(e.caution)}\n\n<b>Integridade informada</b>: ${es(e.integrity)}</div></details><div class="rows"><span class="tag">${es(e.role)}</span><button class="btn sm ${added?'dark':''}" onclick="attachEv('${e.id}')">${added?'✓ Juntada':'Juntar aos autos'}</button><button class="btn sm ghost" onclick="contestEv('${e.id}')">${cont?'✓ Impugnada':'Impugnar / verificar'}</button></div>`:'<p class="mini">Ainda não obtida. Peça diligências para revelar o conteúdo.</p>'}</div></div></div>`}).join('')}</div>`}
function witnessesPage(c,p){return `<div class="panel"><div class="eyebrow">PESSOAS ENVOLVIDAS</div><h2>Quatro vozes, versões nem sempre compatíveis</h2><p>Ninguém é automaticamente confiável ou mentiroso: distinga percepção direta, boatos, interesse e prova documental.</p>${c.witnesses.map(w=>`<div class="witness"><img src="${w.portrait}" alt="Retrato 3D de ${es(w.name)}"><div><div class="rows"><b>${es(w.name)}</b><span class="tag">${es(w.role)}</span><span class="tag gold">Interesse: ${es(w.interest)}</span></div><p><b>Relato conhecido:</b> ${es(w.statement)}</p><p class="mini">Modo de falar: ${es(w.tone)} · Consistência inicial: ${w.credibility}/100 (indicador ficcional, não prova)</p><button class="btn sm dark" onclick="goTab('entrevista')">Entrevistar</button></div></div>`).join('')}</div>`}
function interviewsPage(c,p){return `<div class="cols"><div class="panel"><div class="eyebrow">SALA DE ENTREVISTA</div><h2>Interrogatório com personagens</h2><div class="rows"><img class="portrait" src="${c.cover}" alt="Personagem 3D"><div><span id="aistatus" class="tag">Verificando Gemini...</span><p class="mini">Em modo local, respostas se restringem aos fatos registrados. Gemini depende de uma chave de API no Netlify. Em modo local, as respostas são roteirizadas.</p></div></div><div class="field"><label>Quem você deseja ouvir?</label><select id="personSel">${c.witnesses.map(w=>`<option value="${w.id}">${es(w.name)} — ${es(w.role)}</option>`).join('')}</select></div><div class="field"><label>Faça sua pergunta livremente</label><textarea id="ask" placeholder="Onde estava às 20h? Você viu o documento original? Pode explicar a contradição?"></textarea></div><button class="btn primary" onclick="chat()">Perguntar à testemunha →</button></div><div class="panel"><h3>Registro das falas</h3><div class="chatlog" id="chatlog">${p.messages.length?p.messages.map(x=>`<div class="bubble ${x.role==='player'?'mine':''}"><b>${es(x.who)}</b><br>${es(x.text)}</div>`).join(''):'<div class="emptystate">Nenhuma pergunta ainda. Suas conversas serão registradas no processo.</div>'}</div></div></div>`}
function petitionPage(c,p){return `<div class="cols"><div class="panel"><div class="eyebrow">PEÇA PROCESSUAL</div><h2>Fundamente sua atuação</h2><p>Escreva tese, fatos comprovados, pedidos e referências normativas. Os argumentos livres não são automaticamente verdadeiros.</p><div class="field"><label>Petição ou manifestação</label><textarea id="petition" style="min-height:270px" placeholder="Excelentíssimo juízo... Nos autos..., requer-se..." >${es(p.petition)}</textarea></div><button class="btn primary" onclick="makePetition()">Protocolar manifestação</button></div><div class="panel"><h3>Elementos úteis</h3><p><b>Base normativa indicativa:</b> ${es(c.law)}</p><p><b>Questão controvertida:</b> ${es(c.twist)}</p><h4>Provas já juntadas</h4>${p.attached.length?p.attached.map(id=>`<div class="logentry">• ${es(c.evidence.find(e=>e.id===id)?.title||id)}</div>`).join(''):'<p class="muted">Nenhuma prova vinculada. Abra a aba Provas para juntá-las.</p>'}<div class="warning">O game simplifica prazos e ritos nesta versão; decisões reais envolvem regras específicas, distribuição do ônus e competência.</div></div></div>`}
function hearingPage(c,p){return `<div class="court"><div class="eyebrow">TRIBUNAL · SESSÃO SIMULADA</div><h2>${es(c.venue)}</h2><p>${es(c.title)} · ${es(c.number)}</p><div class="court-people"><img src="data:image/svg+xml;base64," alt="Advogada 3D"><img src="${c.witnesses[0].portrait}" alt="Cliente 3D"><img src="${c.witnesses[1].portrait}" alt="Parte contrária 3D"></div></div><div class="cols" style="margin-top:13px"><div class="panel"><h3>Condução da audiência</h3>${p.phase<2?`<p>Antes de começar, junte duas provas e protocole uma manifestação.</p><button class="btn primary" onclick="startHearing()">Abrir audiência e registrar presença</button>`:p.phase===3?'<div class="success">Audiência encerrada. Ata e decisão disponíveis nos autos.</div>':`<div class="rows"><button class="btn" onclick="hearingAction('contraditorio')">Contraditório</button><button class="btn" onclick="hearingAction('pericia')">Requerer perícia</button><button class="btn" onclick="hearingAction('depoimento')">Ouvir testemunha</button><button class="btn" onclick="hearingAction('impugnacao')">Impugnar prova</button><button class="btn" onclick="hearingAction('acordo')">Propor acordo</button></div><hr class="sepline"><button class="btn primary" onclick="decision()">Encerrar instrução e solicitar decisão</button>`}</div><div class="panel"><h3>Ata em construção</h3><div class="transcript">${p.transcript.length?p.transcript.map(x=>`<div class="logentry"><b>${es(x.who)}:</b> ${es(x.text)}</div>`).join(''):'<p class="muted">A audiência ainda não foi aberta.</p>'}</div></div></div>`}
function autosPage(c,p){return `<div class="panel"><div class="rows between"><div><div class="eyebrow">ARQUIVO PROCESSUAL</div><h2>Documentos e certidões do caso</h2><p class="muted">Cada peça pertence a ${c.id}, sem mistura com outros clientes.</p></div><button class="btn primary" onclick="exportCase()">↓ Exportar autos JSON</button></div>${p.documents.map(d=>`<div class="docentry"><div><b>${es(d.title)}</b><div class="mini">${es(d.type)} · Dia ${d.day}</div></div><button class="btn sm" onclick="readDoc('${d.id}')">Abrir</button></div>`).join('')}<hr class="sepline"><h3>Importar arquivo de comprovação</h3><div class="field"><input type="file" id="uploadFile" accept=".txt,.csv,.json,.pdf,image/*"><small>PDF e imagens são registrados como anexos não verificados; o protótipo não interpreta automaticamente seu conteúdo. Limite 1,5 MB.</small></div><button class="btn" onclick="uploadEvidence()">Adicionar arquivo ao dossiê</button></div>`}
function decisionPage(c,p){return `<div class="cols"><div class="panel"><div class="eyebrow">DESPACHO / SENTENÇA DO JOGO</div><h2>Conclusão da causa</h2>${p.decision?`<span class="tag ${p.decision.score>=9?'green':'red'}">${es(p.decision.result)}</span><pre class="paper">${es(p.decision.text)}</pre><div class="rows"><button class="btn" onclick="goTab('autos')">Abrir decisão e ata</button></div>`:'<div class="warning">Ainda não há conclusão. Passe pela fase de instrução e pela audiência.</div>'}</div><div class="panel"><div class="eyebrow">REVISÃO DO RESULTADO</div><h2>Pedido de reexame</h2><p class="mini">Nem todo recurso é cabível em todo rito ou contra qualquer decisão. Aqui o pedido é apenas registrado para análise, sem reverter automaticamente o julgamento.</p><div class="field"><label>Fundamente o pedido</label><textarea id="revisionText" placeholder="A decisão não enfrentou o documento..., requer-se reexame nos limites do rito..." ${p.decision?'':'disabled'}></textarea></div><button class="btn dark" ${p.decision?'':'disabled'} onclick="revision()">Registrar pedido de revisão/recurso</button>${p.revision.map(r=>`<div class="logentry"><b>Dia ${r.day}:</b> ${es(r.text)}<br><span class="mini">${es(r.status)}</span></div>`).join('')}</div></div>`}
function dossier(){let c=iCur(),p=pCur();if(!c)return '<p>Selecione um caso.</p>';if(!p)return `<h1>${es(c.title)}</h1><p>${es(c.summary)}</p><button class="btn primary" onclick="accept('${c.id}')">Aceitar caso</button>`;return caseHeader(c,p)+({resumo:overview,provas:evidencePage,testemunhas:witnessesPage,entrevista:interviewsPage,custos:familyBudget,peticao:petitionPage,audiencia:hearingPage,autos:autosPage,decisao:decisionPage}[s.tab]||overview)(c,p)}
function myCases(){let arr=CASES.filter(c=>!!s.cases[c.id]);return `<div class="eyebrow">CARTEIRA DO ESCRITÓRIO</div><h1>Meus processos</h1><p>${arr.length} causas aceitas.</p>${arr.length?`<div class="casegrid">${arr.map(caseCard).join('')}</div>`:`<div class="panel emptystate">Seu escritório ainda não possui clientes.<br><button class="btn primary" onclick="nav('casos')">Escolher um caso</button></div>`}`}
function research(){return `<div class="eyebrow">CONSULTA NORMATIVA</div><h1>Biblioteca jurídica</h1><p class="muted">Referências iniciais do simulador. Verifique redação, competência, jurisprudência, atos locais e atualização antes de usar na vida real.</p><div class="cols">${[['Constituição Federal','Garantias fundamentais e princípios de defesa','https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm'],['Código de Processo Civil','Audiências, documentos, provas, ônus probatório e segredo de justiça','https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm'],['Código de Processo Penal','Ritos, defesa, prova penal e Tribunal do Júri','https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'],['Código Civil','Família, contratos, sucessões e responsabilidade civil','https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm'],['Consolidação das Leis do Trabalho','Relações empregatícias e procedimentos trabalhistas','https://www.planalto.gov.br/ccivil_03/decreto-lei/del5452.htm'],['Código de Defesa do Consumidor','Direitos de consumidores e fornecedores','https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm']].map(([n,desc,url])=>`<div class="panel"><h3>${n}</h3><p>${desc}</p><a href="${url}" target="_blank" rel="noopener">Consultar lei em fonte oficial ↗</a></div>`).join('')}</div>`}
function office(){return `<div class="eyebrow">ADMINISTRAÇÃO DO ESCRITÓRIO</div><h1>Gestão e carreira</h1><div class="cols"><div class="panel"><h2>Identidade profissional</h2><div class="field"><label>Nome do advogado no jogo</label><input id="lawyerName" value="${es(s.lawyer)}"></div><button class="btn dark" onclick="s.lawyer=$('lawyerName').value.trim()||'Advogado(a)';refresh();toast('Perfil salvo.')">Salvar perfil</button><hr class="sepline"><h3>Especializações escolhidas</h3>${AREAS.slice(1).map(a=>`<label style="display:inline-block;margin:4px 8px"><input type="checkbox" ${s.careerArea.includes(a)?'checked':''} onchange="careerToggle('${a}',this.checked)"> ${a}</label>`).join('')}<p class="mini">As especializações influenciam a carreira; os 100 casos permanecem acessíveis para teste.</p></div><div class="panel"><h2>Indicadores</h2><div class="tiles" style="grid-template-columns:repeat(2,1fr)"><div class="tile"><strong>${fmt(s.cash)}</strong><small>Caixa simulado</small></div><div class="tile"><strong>${s.reputation}/100</strong><small>Prestígio</small></div><div class="tile"><strong>${s.casesPlayed}</strong><small>Clientes atendidos</small></div><div class="tile"><strong>${Object.values(s.cases).filter(p=>p.status==='Decidido').length}</strong><small>Julgamentos concluídos</small></div></div><hr class="sepline"><button class="btn" onclick="exportSave()">↓ Exportar progresso</button></div></div>`}
function careerToggle(area,on){if(on&&!s.careerArea.includes(area))s.careerArea.push(area);if(!on)s.careerArea=s.careerArea.filter(a=>a!==area);refresh()}
function exportSave(){download(JSON.stringify(s,null,2),'TRIBUNAL_PROGESSO.json','application/json')}
function calendar(){let arr=CASES.filter(c=>s.cases[c.id]);return `<div class="eyebrow">AGENDA E ATA</div><h1>Calendário de atos</h1><div class="panel"><div class="rows between"><h3>Dia ${s.day} da carreira</h3><button class="btn primary" onclick="stepDay()">Avançar um dia</button></div><p>O calendário desta versão é ficcional e não calcula prazos legais efetivos.</p>${arr.map(c=>`<div class="docentry"><div><b>${es(c.title)}</b><div class="mini">${es(s.cases[c.id].status)} · fase ${s.cases[c.id].phase+1}/4</div></div><button class="btn sm" onclick="selected('${c.id}')">Abrir</button></div>`).join('')||'<p>Sem processos em pauta.</p>'}</div>`}
function render(){let navLinks=[['inicio','⌂','Início'],['casos','⚖','100 casos'],['processos','▤','Processos'],['agenda','◷','Agenda'],['biblioteca','§','Leis'],['escritorio','♜','Escritório']];$('root').innerHTML=`<div class="app"><aside class="sidebar"><div class="logo"><i>⚖</i><div><b>TRIBUNAL</b><small>A ARTE DA DEFESA</small></div></div><nav>${navLinks.map(([id,ico,t])=>`<button class="navbtn ${s.view===id||(id==='processos'&&s.view==='dossie')?'active':''}" onclick="nav('${id}')"><span class="sym">${ico}</span>${t}</button>`).join('')}</nav><div class="sfooter">Obra de ficção · sem valor judicial.<br>Personagens e ocorrências inventados.</div></aside><main class="workspace"><div class="topbar"><div class="topuser"><div class="avatar"><img src="data:image/svg+xml;base64," alt="Advogada animada em 3D"></div><div><b>${es(s.lawyer)}</b><div class="mini">Advocacia simulada · Nível ${Math.max(1,Math.floor(s.reputation/10))}</div></div></div><div class="moneybar"><span>◈ <b>${fmt(s.cash)}</b></span><span>★ Prestígio ${s.reputation}</span><span>◷ Dia ${s.day}</span></div></div>${({inicio:dashboard,casos:casesPage,processos:myCases,dossie:dossier,agenda:calendar,biblioteca:research,escritorio:office}[s.view]||dashboard)()}<div class="footer">TRIBUNAL — A Arte da Defesa · 100 casos · arquivo confidencial · decisões ficcionais · Animações 3D estilizadas por CSS. Documentos fictícios e decisões didáticas; sem validade jurídica.</div></main></div>`;if(s.view==='dossie'&&s.tab==='entrevista'){let log=$('chatlog');if(log)log.scrollTop=log.scrollHeight}}
render();

/* TRIBUNAL 3.0 — camada de processos com eventos, agenda e contraditório.
 * Sem dependências, preserva 100 dossiês, saves e integração Gemini.
 * Intervalos de dias são artificiais e NÃO substituem prazo processual brasileiro. */
(()=>{
'use strict';
const previous={accept,makePetition,hearingAction,revision,caseHeader,overview,dashboard,calendar,hearingPage,decisionPage,petitionPage,office,dossier,evidencePage};
const BASE_DATE='2026-10-25';
const $id=x=>document.getElementById(x);
const iff=(b,a,c='')=>b?a:c;
const labels={autuacao:'Autuação e conferência',contraditorio:'Manifestação da parte contrária',saneamento:'Organização da instrução',audiencia:'Audiência designada',pronuncia:'Exame da pronúncia',plenario:'Sessão do Tribunal do Júri',julgamento:'Publicação da decisão',recurso:'Exame do recurso',prazo:'Prazo de manifestação da defesa',diligencia:'Entrega de diligência investigativa'};
function dateOf(d){let x=new Date(`${BASE_DATE}T12:00:00Z`);x.setUTCDate(x.getUTCDate()+d-1);return x.toLocaleDateString('pt-BR',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric'});}
function kind(c){if(c.area==='Penal')return !/culposo/i.test(c.kind)&&/homic[ií]dio|feminic[ií]dio|infantic[ií]dio|aborto doloso/i.test(c.kind)?'juri':'penal';if(c.area==='Família')return 'familia';if(c.area==='Trabalhista')return 'trabalhista';return 'civil';}
function kindName(c){return ({juri:'Procedimento do Tribunal do Júri (simplificado)',penal:'Procedimento penal (simplificado)',familia:'Ação de família (simplificada)',trabalhista:'Procedimento trabalhista (simplificado)',civil:'Procedimento cível (simplificado)'})[kind(c)];}
function flow(p,c){if(!p||!c)return null;if(!p.workflow){p.workflow={version:3,opened:s.day,filed:null,events:[],courtStage:'triagem',heard:false,hearingOpened:false,hearingDate:null,closing:null,pronuncia:null,plenary:false,nextDeadline:null,missed:false,counterFiled:false,counterText:'',responseReceived:false,notices:[],appealDate:null,appealResult:null};if(p.decision){p.workflow.courtStage='decidido';p.workflow.heard=true}else if(p.petition){p.workflow.courtStage='peticao_antiga';p.workflow.notices.push({day:s.day,title:'Peça legada detectada',text:'Esta partida foi criada numa edição anterior. Protocole uma nova manifestação para ativar o calendário detalhado.'});}}
if(!Array.isArray(p.workflow.events))p.workflow.events=[];
return p.workflow;}
function evt(c,p,type,day,detail){let f=flow(p,c);let id=type+'-'+day+'-'+f.events.length;if(!f.events.some(e=>e.id===id)){f.events.push({id,type,day,detail,done:false});f.events.sort((a,b)=>a.day-b.day);}return f.events.find(e=>e.id===id);}
function notice(c,p,title,message){let f=flow(p,c);f.notices.unshift({day:s.day,title,text:message});f.notices=f.notices.slice(0,25);recordCaseHistory(p,`${title} — ${message}`);}
function paper(c,p,title,body,type='Certidão'){doc(p,c,title,`${title.toUpperCase()} · SIMULAÇÃO\nAutos ${c.number}\nDia ${s.day} · ${dateOf(s.day)}\n\n${body}\n\nRegistro inteiramente fictício, sem validade forense.`,type);}
function initCalendar(c,p){let f=flow(p,c);if(f.filed)return;f.filed=s.day;const d=c.difficulty,t=kind(c);f.courtStage='distribuido';
const hearingOffset=t==='civil'?42+d*3:t==='familia'?24+d*4:t==='trabalhista'?22+d*3:t==='juri'?34+d*4:29+d*3;
const dates={autuacao:s.day+2,contraditorio:s.day+8+d*2,saneamento:s.day+15+d*2,audiencia:s.day+hearingOffset};
f.hearingDate=dates.audiencia;
evt(c,p,'autuacao',dates.autuacao,'Conferência dos autos e identificação das partes');
evt(c,p,'contraditorio',dates.contraditorio,'Manifestação do Ministério Público ou da parte contrária');
evt(c,p,'saneamento',dates.saneamento,'Determinação sobre provas e organização do ato seguinte');
evt(c,p,'audiencia',dates.audiencia,'Comparecimento do jogador necessário para realizar a audiência');
notice(c,p,'Petição recebida',`Autuação simulada marcada para o dia ${dates.autuacao}; próxima audiência prevista para o dia ${dates.audiencia} (${dateOf(dates.audiencia)}).`);
paper(c,p,'Comprovante de protocolo',`Petição recebida no expediente digital fictício. Não se trata de protocolo em tribunal real.\nPróximo movimento: ${dateOf(dates.autuacao)}.\nAgenda de audiência: ${dateOf(dates.audiencia)}.`, 'Protocolo');}
function caseDue(f){return f.events.filter(e=>!e.done).sort((a,b)=>a.day-b.day)[0]||null;}
function workDay(c,p){let f=flow(p,c);if(!f.filed&&!f.events.some(e=>e.type==='diligencia'&&!e.done))return;
for(const e of f.events.filter(e=>!e.done&&e.day<=s.day)){
e.done=true;
if(e.type==='diligencia'){
  const proof=c.evidence.find(x=>x.id===e.evidenceId);
  if(proof&&!p.selected.includes(proof.id)){
    p.selected.push(proof.id);p.investigations++;
    notice(c,p,'Diligência cumprida',`Documento obtido: ${proof.title}. Sua origem e limitações devem ser analisadas antes da juntada.`);
    paper(c,p,'Termo de diligência — '+proof.title, evidencePaper(c,proof),'Diligência');
  }
}
if(e.type==='autuacao') {f.courtStage='autuado';notice(c,p,'Distribuição e autuação',`Autos autuados sob nº ${c.number}. Competência indicada: ${c.venue}.`);paper(c,p,'Certidão de autuação',`Processo cadastrado e autuado. Tramitação ativa. Vara indicada: ${c.venue}.`);}
if(e.type==='contraditorio') {f.responseReceived=true;f.courtStage='contraditorio';f.nextDeadline=s.day+7;notice(c,p,'Manifestação adversa juntada',`A contraparte apresentou sua versão. Defesa pode responder até o dia ${f.nextDeadline}, prazo apenas do jogo.`);paper(c,p,kind(c)==='juri'?'Manifestação do Ministério Público':'Contestação / manifestação da parte contrária',`PARTE CONTRÁRIA: ${c.opponent}\n\n${c.opponentClaim}\n\nRequer exame crítico das provas e impugna as alegações de ${c.client}.\nA manifestação não converte alegações em fatos comprovados.`, 'Manifestação adversa');}
if(e.type==='saneamento') {f.courtStage='instrução';notice(c,p,'Despacho de organização',`Delimitada a controvérsia: ${c.twist}. Intimação para a audiência no dia ${f.hearingDate}.`);paper(c,p,'Despacho de organização do processo',`Questões controvertidas: ${c.twist}\nProvas vinculadas até agora: ${p.attached.join(', ')||'nenhuma'}.\nAudiência: dia ${f.hearingDate} (${dateOf(f.hearingDate)}).\nA pertinência, autenticidade e suficiência das provas ainda serão examinadas.`, 'Despacho');}
if(e.type==='audiencia'){f.courtStage='audiencia_disponivel';notice(c,p,'Audiência na pauta',`Audiência disponível hoje, dia ${s.day}. Abra a aba Audiência para comparecer.`);}
if(e.type==='plenario'){if(p.oral)p.oral={answers:[],heard:[],confronted:[]};f.courtStage='plenario_disponivel';f.hearingOpened=false;f.heard=false;p.hearingActions=[];notice(c,p,'Plenário do Júri designado',`Realize o plenário. A decisão anterior de pronúncia não significa condenação.`);}
if(e.type==='julgamento'){publishDecision(c,p);}
if(e.type==='recurso'){processAppeal(c,p);}
}
if(f.nextDeadline && s.day>f.nextDeadline && !f.counterFiled && !f.missed && f.responseReceived){f.missed=true;notice(c,p,'Prazo fictício ultrapassado','Você não registrou resposta no prazo do jogo. Ainda pode se manifestar, mas o atraso será considerado pelo motor didático.');paper(c,p,'Certidão de prazo transcorrido','Não foi identificada resposta tempestiva da defesa à manifestação adversa. A certidão refere-se apenas ao calendário artificial do jogo.');}
if(['audiencia_disponivel','plenario_disponivel'].includes(f.courtStage)&&s.day>f.hearingDate+1&&!f.hearingOpened){
  f.absences=(f.absences||0)+1;
  const old=f.hearingDate;
  f.hearingDate=s.day+14+c.difficulty*2;
  f.courtStage='audiencia_remarcada';
  s.cash-=450;s.reputation=Math.max(0,s.reputation-1);
  notice(c,p,'Ausência na audiência',`A audiência marcada para o dia ${old} não foi realizada. Nova sessão no dia ${f.hearingDate}; custo de deslocamento e remarcação do jogo: R$ 450.`);
  paper(c,p,'Certidão de ausência e redesignação',`Ausência/ausência de condução do ato no dia ${old}. Nova sessão em ${dateOf(f.hearingDate)}. Esta é uma consequência fictícia de gameplay e NÃO representa a consequência legal automática de uma falta.`, 'Certidão');
  evt(c,p,f.plenary?'plenario':'audiencia',f.hearingDate,'Redesignação após ausência do jogador');
}
}
function progressDays(n){const count=Math.min(31,Math.max(1,Number(n)||1));let moved=0,paused='';for(let i=0;i<count;i++){s.day++;moved++;
let critical=[];for(const c of CASES){let p=s.cases[c.id];if(p){const before=flow(p,c).events.filter(e=>!e.done&&e.day===s.day&&['contraditorio','audiencia','plenario','diligencia','julgamento','recurso'].includes(e.type));workDay(c,p);if(before.length)critical.push(c.client+': '+labels[before[0].type]);}}
if(s.day%30===0&&s.v9?.career!=='public'){const operating=3000+Object.keys(s.cases).filter(id=>s.cases[id].status!=='Decidido'&&s.cases[id].v7?.accepted!==false).length*140;s.cash-=operating;s.logs.unshift({day:s.day,caseId:'ESCRITÓRIO',text:`Despesas operacionais do mês: ${fmt(operating)} (aluguel, equipe e gestão de pastas).`});}
if(count>1&&critical.length){paused=critical.slice(0,2).join('; ');break;}}
s.logs.unshift({day:s.day,caseId:'GERAL',text:`Calendário avançado ${moved} dia(s).`});refresh();toast(paused?`Avanço pausado no dia ${s.day}: ${paused}. Consulte a agenda.`:`Agora é o dia ${s.day} (${dateOf(s.day)}). Confira suas intimações.`);}
stepDay=function(){progressDays(1)};
window.advanceTime=progressDays;
accept=function(id){previous.accept(id);let c=get(id),p=s.cases[id];if(p){flow(p,c);refresh()}};
makePetition=function(){const c=iCur(),p=pCur();if(!p)return;const val=$id('petition')?.value.trim()||'';if(val.length<80){toast('A peça precisa desenvolver fatos, fundamentos e pedido (mínimo 80 caracteres).');return;}
const already=!!flow(p,c).filed;
previous.makePetition();if(!already){initCalendar(c,p);}else{notice(c,p,'Manifestação complementar','Peça incluída e submetida à apreciação futura. Datas já marcadas foram preservadas.');}
refresh();};
// Investigações não entregam provas instantaneamente: têm custo e prazo de entrega.
revealNext=function(){let c=iCur(),p=pCur();if(!p)return;let f=flow(p,c);
let occupied=new Set(f.events.filter(x=>x.type==='diligencia'&&!x.done).map(x=>x.evidenceId));
let available=c.evidence.filter(e=>!p.selected.includes(e.id)&&!occupied.has(e.id));
let eid=$id('diligenceTarget')?.value||available[0]?.id;
let e=available.find(x=>x.id===eid);if(!e)return toast('Nenhuma diligência disponível; confira as provas já obtidas e aquelas em andamento.');
let wait=3+c.difficulty*2+(e.type==='Laudo'?4:0);
let cost=e.type==='Laudo'?850:350+c.difficulty*100;
if(s.cash<cost)return toast(`Caixa do escritório insuficiente para a diligência de ${fmt(cost)}.`);
s.cash-=cost;
const due=s.day+wait;
const scheduled=evt(c,p,'diligencia',due,`Investigação de ${e.title} — custo fictício ${fmt(cost)}.`);
scheduled.evidenceId=e.id;
notice(c,p,'Diligência solicitada',`A obtenção de ${e.title} está prevista para o dia ${due} (${dateOf(due)}). A prova pode favorecer ou contrariar a defesa.`);
refresh();toast(`Diligência agendada. Resultado em ${wait} dias fictícios.`);};
evidencePage=function(c,p){let original=previous.evidencePage(c,p),f=flow(p,c),pending=f.events.filter(x=>x.type==='diligencia'&&!x.done).map(x=>x.evidenceId);
let left=c.evidence.filter(x=>!p.selected.includes(x.id)&&!pending.includes(x.id));
const card=`<div class="panel"><div class="eyebrow">INVESTIGAÇÃO PROFISSIONAL</div><h3>Solicitar nova diligência</h3><p>O trabalho agora leva tempo e gera custo. Nenhuma prova aparece imediatamente após o pedido.</p><div class="field"><label>Objeto da diligência</label><select id="diligenceTarget">${left.map(e=>`<option value="${e.id}">${es(e.title)} · ${e.type}</option>`).join('')}</select></div><button class="btn primary" onclick="revealNext()" ${left.length?'':'disabled'}>Solicitar diligência e agendar entrega</button><p class="mini">Valor estimado a partir de R$ 450; laudos podem custar mais. Prazo: 5 a 17 dias de jogo conforme complexidade. Não constitui investigação real.</p>${pending.map(id=>{let event=f.events.find(x=>x.evidenceId===id&&!x.done);return `<div class="v3-notice"><b>Em andamento:</b> ${es(c.evidence.find(e=>e.id===id)?.title||id)}<p>Entrega prevista para dia ${event?.day}.</p></div>`}).join('')}</div>`;
original=original.replace(/<button class="btn primary" onclick="revealNext\(\)">[\s\S]*?<\/button>/,'');
return card+original;};
window.speakAtHearing=function(){let c=iCur(),p=pCur(),f=flow(p,c);if(!f?.hearingOpened)return toast('A audiência precisa estar aberta.');let speech=$id('courtSpeech')?.value.trim()||'';if(speech.length<35)return toast('Desenvolva seu requerimento ou argumento com pelo menos 35 caracteres.');
const ids=p.attached.filter(id=>speech.toLowerCase().includes(id.toLowerCase()));
const key=/(per[ií]cia|dilig[eê]ncia|cadeia de cust[oó]dia|contradi[cç][aã]o|laudo)/i.test(speech);
const answer=ids.length?`O juízo registra a referência à prova ${ids.join(', ')} e determina o exame de sua pertinência no conjunto probatório.`:key?'Pedido técnico consignado. A necessidade da diligência será apreciada à vista das provas já admitidas.':'A alegação foi registrada, mas deverá ser vinculada a fatos e elementos concretos dos autos.';
p.transcript.push({who:s.lawyer,text:speech});p.transcript.push({who:'Juízo',text:answer});p.hearingActions.push('sustentacao');notice(c,p,'Sustentação/requerimento oral','Argumento registrado integralmente na ata e submetido a análise.');refresh();};
window.submitContradictory=function(){let c=iCur(),p=pCur(),f=flow(p,c);if(!f?.responseReceived)return toast('Ainda não houve manifestação da parte contrária.');let value=$id('counterText')?.value.trim()||'';if(value.length<70)return toast('Escreva uma resposta fundamentada (mínimo 70 caracteres).');f.counterFiled=true;f.counterText=value;notice(c,p,'Réplica / resposta apresentada',f.missed?'Manifestação juntada fora do prazo didático; sujeito a exame pelo juízo.':'Manifestação juntada no prazo didático.');paper(c,p,'Manifestação da defesa à parte contrária',`Resposta às alegações de ${c.opponent}:\n\n${value}\n\nProvas juntadas: ${p.attached.join(', ')||'Nenhuma'}\nImpugnações: ${p.challenged.join(', ')||'Nenhuma'}`, 'Peça da defesa');refresh();};
function canStart(c,p){let f=flow(p,c);return f.filed&&['audiencia_disponivel','plenario_disponivel'].includes(f.courtStage)&&s.day>=f.hearingDate&&!f.hearingOpened;}
startHearing=function(){let c=iCur(),p=pCur();if(!p)return;let f=flow(p,c);if(!f.filed)return toast('Protocole uma peça primeiro. O processo precisará tramitar.');if(s.day<f.hearingDate)return toast(`Audiência agendada para o dia ${f.hearingDate} (${dateOf(f.hearingDate)}).`);if(!canStart(c,p))return toast('O processo não está na fase de abertura de audiência. Confira o andamento.');
f.hearingOpened=true;f.courtStage=f.plenary?'plenario_em_curso':'audiencia_em_curso';p.phase=2;
p.transcript.push({who:'Serventia',text:`Abertura ${f.plenary?'do plenário do Tribunal do Júri':'da audiência'} no dia ${s.day} (${dateOf(s.day)}). Partes e representantes intimados no universo fictício.`});p.transcript.push({who:'Contraparte',text:c.opponentClaim});
notice(c,p,f.plenary?'Plenário iniciado':'Audiência iniciada','A ata está sendo produzida. Faça requerimentos pertinentes e encerre a instrução quando houver elementos suficientes.');refresh();};
hearingAction=function(a){let c=iCur(),p=pCur();if(!p?.workflow?.hearingOpened)return toast('A audiência ainda não foi aberta ou já foi encerrada.');if(!['contraditorio','pericia','acordo','depoimento','impugnacao'].includes(a))return;
if(a==='acordo'&&['penal','juri'].includes(kind(c)))return toast('Este caso não comporta um acordo civil genérico no lugar do rito criminal.');
if(a==='depoimento'&&p.witnessQuestionCount===0){p.transcript.push({who:'Juízo',text:'Oitiva deferida em tese, mas nenhuma entrevista prévia foi registrada. Isso não impede a prova oral judicial.'});}
previous.hearingAction(a);};
window.closeInstruction=function(){let c=iCur(),p=pCur(),f=flow(p,c);if(!f?.hearingOpened)return toast('Abra e realize a audiência antes de encerrar a instrução.');
f.hearingOpened=false;f.heard=true;f.courtStage='concluso';p.transcript.push({who:'Serventia',text:'Instrução encerrada; autos conclusos para apreciação, sem decisão imediata.'});paper(c,p,'Ata de audiência',minutesText(c,p),'Ata');
let due=s.day+(f.plenary?1:5+c.difficulty*2);f.closing=s.day;evt(c,p,'julgamento',due, f.plenary?'Votação fictícia do plenário':'Decisão após exame dos autos');notice(c,p,'Autos conclusos',`Decisão prevista para o dia ${due} (${dateOf(due)}), salvo necessidade de diligências.`);refresh();};
// Mantém onclick legado, mas decisão não pode ser instantânea
 decision=function(){window.closeInstruction()};
function legalEvaluation(c,p){const f=flow(p,c),attached=p.attached.map(id=>c.evidence.find(e=>e.id===id)).filter(Boolean);const weight=attached.reduce((sum,e)=>sum+Number(e.weight||0),0);
const text=[p.petition,f.counterText].join(' ').toLowerCase();const grounded=attached.filter(e=>text.includes(e.id.toLowerCase())||text.includes(e.title.toLowerCase().slice(0,16))).length;
const trace= p.challenged.filter(id=>p.selected.includes(id)).length;
const oral=p.witnessQuestionCount>0?1:0;
const argument=/(art\.|lei |c[oó]digo|contradit[oó]rio|autoria|materialidade|[ôo]nus|interesse da crian[cç]a|proporcionalidade|nexo causal|prescri[cç][aã]o)/i.test(text)?2:0;
const assessment=window.__TRIBUNAL_V4__?.assess(c,p);const score=assessment?assessment.score:0;
return {score,attached,grounded,weight,trace,oral,argument,assessment:window.__TRIBUNAL_V4__?.assess(c,p)};}
function publishDecision(c,p){if(window.T9?.shouldPauseDecision?.(c,p))return;let f=flow(p,c);if(!f.heard||p.decision)return;const ev=legalEvaluation(c,p);const isJury=kind(c)==='juri';
if(isJury&&!f.plenary){
 f.pronuncia={day:s.day,result:ev.assessment?.defenseDoubt?'Impronúncia na fase preliminar (simulação)':'Pronúncia (indícios para exame do Júri, sem condenação)',score:ev.score};
 let pronounce=f.pronuncia.result;paper(c,p,'Decisão da primeira fase do Júri',`Procedimento do Júri — fase preliminar.\nResultado: ${pronounce}.\nO exame é sobre materialidade e indícios de autoria; não equivale a juízo de culpa final.\nQuestão central: ${c.twist}.\nProvas consideradas: ${ev.attached.map(x=>x.title).join('; ')||'nenhuma'}.\nEtapa didática sem representação fiel de todos os incidentes e recursos.`, 'Decisão interlocutória');
 if(!ev.assessment?.defenseDoubt){f.plenary=true;f.courtStage='aguardando_plenario';f.hearingDate=s.day+21+c.difficulty*4;evt(c,p,'plenario',f.hearingDate,'Sessão fictícia de plenário após a pronúncia');notice(c,p,'Pronúncia registrada',`Encaminhamento para eventual plenário no dia ${f.hearingDate}; não houve condenação.`);p.phase=1;
 }else{f.courtStage='decidido';f.appealUntil=s.day+10;const result='Impronúncia — fase preliminar';const summary=`DECISÃO FICTÍCIA — FASE PRELIMINAR DO JÚRI\n${c.number}\n${result}.\nIndícios não considerados suficientes nesta simulação.\nPontuação didática interna: ${ev.score.toFixed(1)}.\nNão substitui os dispositivos processuais brasileiros.`; p.decision={result,text:summary,score:ev.score,day:s.day};p.status='Decidido';paper(c,p,'Decisão da fase preliminar',summary,'Decisão');notice(c,p,'Decisão preliminar publicada',result);}
 return;
}
let result=ev.score>=14?(c.judgmentPlan?.ruling||'Tese acolhida nos limites demonstrados'):ev.score>=8?(c.judgmentPlan?.partial||'Acolhimento parcial / necessidade de ajustes'):'Tese não acolhida por insuficiência de instrução nesta simulação';
if(window.Tribunal5)result=Tribunal5.disposition(c,p,result,ev.score);
if(isJury){result=ev.score>=14?'Veredicto simulado favorável à tese defensiva':ev.score>=8?'Veredicto simulado parcialmente favorável':'Veredicto simulado desfavorável à defesa';}
const rationale=[...(ev.assessment?.reasoning||[]),`A apreciação distingue a narrativa de ${c.client} e a alegação de ${c.opponent}.`,`Questão probatória examinada: ${c.twist}.`,c.judgmentPlan?.limit||'',`Documentos juntados e avaliados: ${ev.attached.length}.`,`A fundamentação considera documentos relacionados aos pontos controvertidos, não a soma de pesos favoráveis.`,`Referências concretas a peças/documentos nos argumentos: ${ev.grounded}.`,`Impugnações formalizadas: ${ev.trace}.`,`Manifestação em contraditório: ${f.counterFiled?'apresentada':'não apresentada'}.`,f.missed?'Houve atraso no prazo exclusivamente fictício de manifestação.':'',`As provas têm origens, limites e possibilidades de contestação. A decisão não decorre simplesmente do tamanho da petição.`].filter(Boolean).join('\n');
const title=isJury?'REGISTRO DE VEREDICTO SIMULADO':'SENTENÇA SIMULADA';const summary=`${title}\nProcesso: ${c.number}\nÁrea: ${c.area}\nParte representada: ${c.client}\n\nRESULTADO\n${result}\n\nFUNDAMENTAÇÃO PEDAGÓGICA\n${rationale}\n\nAVISO: O resultado é de um motor de jogo, NÃO de tribunal real; os prazos simulados não são prazos legais.\nPontuação técnica interna: ${ev.score.toFixed(1)}.`;
p.decision={result,score:ev.score,text:summary,day:s.day,outcome:window.Tribunal5?Tribunal5.outcomeFor(c,p,ev.score):(ev.score>=14?(c.judgmentPlan?.outcome||'favoravel'):ev.score>=8?'parcial':'desfavoravel')};p.phase=3;p.status='Decidido';f.courtStage='decidido';f.decisionDay=s.day;f.appealUntil=s.day+10;paper(c,p,isJury?'Resultado do plenário':'Sentença fundamentada simulada',summary,'Decisão');notice(c,p,'Decisão publicada',`${result}. Para o jogo, pedido de reexame disponível até o dia ${f.appealUntil}.`);
const honor=0;/* Edição VI: recebimentos dependem do contrato e das parcelas. */s.reputation=Math.max(0,Math.min(100,s.reputation+(ev.score>=8?2:-2)));}
revision=function(){let c=iCur(),p=pCur(),f=flow(p,c);if(!p?.decision)return toast('Ainda não há decisão publicada.');if(f.appealDate)return toast('Já há um recurso pendente deste processo.');if(s.day>f.appealUntil)return toast(`Prazo fictício de reexame encerrado no dia ${f.appealUntil}.`);
const reason=$id('revisionText')?.value.trim()||'';if(reason.length<60)return toast('Descreva especificamente o erro ou omissão (mínimo 60 caracteres).');f.appealDate=s.day;f.appealReason=reason;const day=s.day+8+c.difficulty*2;evt(c,p,'recurso',day,'Análise de admissibilidade e mérito simulada');p.revision.push({day:s.day,text:reason,status:'Aguardando análise da instância revisora'});paper(c,p,'Interposição de recurso didático',`Razões: ${reason}\nA admissibilidade não é garantida.\nExame previsto para o dia ${day}.`,'Recurso');notice(c,p,'Recurso protocolado',`Exame marcado para o dia ${day} (${dateOf(day)}).`);refresh();};
function processAppeal(c,p){let f=flow(p,c);if(!f.appealDate||f.appealResult)return;const prior=p.decision?.score??0;
const convincing=/(omiss[aã]o|contradi[cç][aã]o|nulidade|erro material|documento|per[ií]cia|art\.|cerceamento)/i.test(f.appealReason)&&f.appealReason.length>90;
const reasons=String(f.appealReason||'').toLowerCase();const specific=p.attached.some(id=>reasons.includes(id.toLowerCase()));const changed=convincing&&specific&&prior>=6&&prior<14;
f.appealResult=changed?'Reforma parcial da decisão (simulação)':'Decisão mantida após exame do pedido';
if(changed){p.decision.result='Decisão parcialmente reformada em grau revisional';p.decision.text+='\n\nRESULTADO DE RECURSO: reforma parcial por elementos já documentados e impugnação da prova.';}
p.revision[p.revision.length-1].status=f.appealResult;paper(c,p,'Acórdão / decisão revisional fictícia',`Resultado: ${f.appealResult}\nFundamento didático: ${convincing?'O recurso apontou questão juridicamente relevante, confrontada com as provas juntadas.':'O recurso não identificou fundamento apto à alteração segundo o motor.'}\nNenhum recurso real foi interposto.`,'Decisão revisional');notice(c,p,'Recurso analisado',f.appealResult);}
// Widgets de jogo e acompanhamento
function proceduralCard(c,p){let f=flow(p,c),n=caseDue(f);let actions=[];
if(!f.filed)actions.push(['Protocolar petição','peticao']);
else if(f.responseReceived&&!f.counterFiled)actions.push(['Responder à manifestação adversa','andamentos']);
if(['audiencia_disponivel','plenario_disponivel'].includes(f.courtStage))actions.push(['Comparecer à audiência','audiencia']);
if(f.hearingOpened)actions.push(['Conduzir instrução','audiencia']);
return `<section class="panel v3-monitor"><div class="v3-row"><div><div class="eyebrow">ACOMPANHAMENTO DO PROCESSO</div><h3>${es(kindName(c))}</h3><p>Status: <b>${es(stageName(f.courtStage))}</b></p></div><div class="v3-stamp"><strong>${dateOf(s.day)}</strong><small>Dia ${s.day} do jogo</small></div></div><div class="v3-row"><p>Próximo ato: <b>${n?es(labels[n.type]||n.type):'Nenhum ato agendado'}</b></p><p>${n?'Dia '+n.day+' · '+dateOf(n.day):'—'}</p></div><div class="v3-cta">${actions.map(([name,tab])=>`<button class="btn sm dark" onclick="goTab('${tab}')">${name}</button>`).join('')}<button class="btn sm" onclick="goTab('andamentos')">Ver andamentos e intimações</button></div></section>`;}
function stageName(q){return ({triagem:'Atendimento / triagem',peticao_antiga:'Aguardando ativação do fluxo',distribuido:'Distribuição protocolada',autuado:'Processo autuado',contraditorio:'Contraditório aberto',instrução:'Instrução organizada',audiencia_disponivel:'Audiência na pauta',audiencia_em_curso:'Audiência em curso',concluso:'Concluso para decisão',aguardando_plenario:'Aguardando plenário',plenario_disponivel:'Plenário disponível',plenario_em_curso:'Plenário em andamento',decidido:'Decisão publicada'})[q]||q;}
function proceedings(c,p){const f=flow(p,c),evs=f.events.slice().sort((a,b)=>a.day-b.day);let forthcoming=evs.filter(e=>!e.done);return `${proceduralCard(c,p)}<div class="v3-grid"><section class="panel"><div class="eyebrow">AUTOS DIGITAIS</div><h2>Andamentos e movimentações</h2><p class="muted">Cada ato aparece na data agendada. Não existe decisão instantânea após uma petição.</p><div class="v3-timeline">${evs.length?evs.map(e=>`<div class="v3-event ${e.done?'complete':e.day<s.day?'late':''}"><div class="v3-dot"></div><div><b>${e.day} · ${es(labels[e.type]||e.type)}</b><small>${dateOf(e.day)} · ${e.done?'Movimentação registrada':'Aguardando'}</small><p>${es(e.detail)}</p></div></div>`).join(''):'<div class="muted">Protocole sua primeira peça para iniciar a tramitação.</div>'}</div></section><section class="panel"><div class="eyebrow">DIÁRIO DE JUSTIÇA FICTÍCIO</div><h2>Intimações e contraditório</h2>${f.notices.slice(0,8).map(n=>`<div class="v3-notice"><b>Dia ${n.day} · ${es(n.title)}</b><p>${es(n.text)}</p></div>`).join('')||'<p>Nenhuma intimação publicada.</p>'}${f.responseReceived?`<hr class="sepline"><h3>Responder à parte contrária</h3><p>${f.counterFiled?'Sua manifestação já está juntada aos autos.':`Prazo exclusivamente do jogo: dia ${f.nextDeadline}.`}</p><textarea id="counterText" style="min-height:160px" placeholder="Enfrente as alegações adversas, cite documentos e exponha os pedidos..." ${f.counterFiled?'disabled':''}>${es(f.counterText)}</textarea><button class="btn primary" onclick="submitContradictory()" ${f.counterFiled?'disabled':''}>Protocolar resposta fundamentada</button>`:'<p class="muted">A manifestação da outra parte aparecerá aqui quando juntada.</p>'}</section></div><div class="panel"><h3>Avançar a tramitação</h3><div class="v3-cta"><button class="btn primary" onclick="advanceTime(1)">+1 dia</button><button class="btn" onclick="advanceTime(7)">+7 dias</button><button class="btn" onclick="advanceTime(30)">+30 dias</button></div><p class="mini">Os prazos exibidos são convenções do simulador. O calendário real de tribunais envolve regras processuais, dias úteis, feriados, suspensão e intimação válida.</p></div>`;}
caseHeader=function(c,p){flow(p,c);let base=previous.caseHeader(c,p);const f=flow(p,c);let current=`<div class="v3-case-bar"><span>Dia ${s.day} · ${dateOf(s.day)}</span><b>${es(stageName(f.courtStage))}</b><span>Próximo ato: ${es(caseDue(f)?'dia '+caseDue(f).day:'sem data')}</span></div>`;
base=base.replace(`<div class="tabs">`,`<div class="tabs"><button class="${s.tab==='andamentos'?'active':''}" onclick="goTab('andamentos')">⚑ Andamentos / intimações</button><button class="${s.tab==='guia'?'active':''}" onclick="goTab('guia')">ⓘ Como jogar</button>`);
const stages=kind(c)==='juri'?['Triagem','Contraditório','Instrução','Pronúncia','Plenário','Veredicto']:['Triagem','Contraditório','Instrução','Audiência','Decisão'];
const pos=!f.filed?0:f.decision?stages.length-1:f.plenary?4:f.pronuncia?3:f.hearingOpened?3:f.responseReceived?2:1;
const steps=`<div class="steps">${stages.map((x,i)=>`<span class="step ${i===pos?'active':i<pos?'done':''}">${i+1}. ${x}</span>`).join('')}</div>`;
base=base.replace(/<div class="steps">[\s\S]*?<\/div>/,steps);
return current+base;};
overview=function(c,p){return proceduralCard(c,p)+previous.overview(c,p)};
petitionPage=function(c,p){const f=flow(p,c);return `<div class="v3-legal-hint"><b>Antes de protocolar:</b> uma petição não provoca sentença imediata. Depois do protocolo, a outra parte poderá se manifestar e o juízo pautará atos. Use números/nomes de provas em sua tese. ${f.filed?'Este processo já possui protocolo ativo; novas peças serão complementares.':'Esta será sua primeira manifestação no fluxo do processo.'}</div>`+previous.petitionPage(c,p);};
hearingPage=function(c,p){const f=flow(p,c),yes=canStart(c,p);let top=proceduralCard(c,p);const status=f.hearingOpened?`<div class="panel"><h3>Audiência em andamento</h3><p>Rito: ${es(kindName(c))}. As decisões e requerimentos ficarão na ata.</p></div>`:f.heard?`<div class="panel"><h3>Instrução encerrada</h3><p>O juízo ainda precisa examinar o processo. Consulte a agenda para a data prevista.</p></div>`:`<div class="panel"><h3>Preparação da sessão</h3><p>${f.filed?`Data prevista: <b>dia ${f.hearingDate}</b> (${dateOf(f.hearingDate)}).`:'Primeiro protocole sua peça processual.'}</p><p>${yes?'O ato já está na pauta. A abertura dependerá do seu comparecimento.':'Ainda não é possível abrir a audiência.'}</p></div>`;
let base=`<div class="court"><div class="eyebrow">${f.plenary?'PLENÁRIO DO TRIBUNAL DO JÚRI':'SALA DE AUDIÊNCIAS'} · SIMULAÇÃO</div><h2>${es(c.venue)}</h2><p>${es(c.title)} · ${es(c.number)}</p><div class="court-people"><img src="data:image/svg+xml;base64," alt="Advogada 3D"><img src="${c.witnesses[0].portrait}" alt="Cliente 3D"><img src="${c.witnesses[1].portrait}" alt="Parte contrária 3D"></div></div><div class="v3-grid"><div class="panel"><h3>Atos da defesa</h3>${f.hearingOpened?`<div class="v3-cta"><button class="btn" onclick="hearingAction('contraditorio')">Garantir contraditório</button><button class="btn" onclick="hearingAction('depoimento')">Ouvir testemunha</button><button class="btn" onclick="hearingAction('pericia')">Pedir perícia</button><button class="btn" onclick="hearingAction('impugnacao')">Impugnar prova</button>${kind(c)==='juri'||kind(c)==='penal'?'':'<button class="btn" onclick="hearingAction(&quot;acordo&quot;)">Propor acordo</button>'}</div><div class="field" style="margin-top:14px"><label>Argumentação oral ou requerimento livre</label><textarea id="courtSpeech" placeholder="Excelência, a prova CASO-... é contraditória porque... Requeiro..." style="min-height:105px"></textarea></div><button class="btn" onclick="speakAtHearing()">Registrar fala e obter manifestação do juízo</button><hr class="sepline"><button class="btn primary" onclick="closeInstruction()">Encerrar instrução e remeter à decisão</button>`:`<button class="btn primary" onclick="startHearing()" ${yes?'':'disabled'}>Comparecer e abrir audiência</button>`}<p class="mini">Ata e desfecho não são automáticos. Um pleito pode ser deferido, indeferido ou permanecer pendente conforme o contexto.</p></div><div class="panel"><h3>Ata em construção</h3><div class="transcript">${p.transcript.map(x=>`<div class="logentry"><b>${es(x.who)}:</b> ${es(x.text)}</div>`).join('')||'Nenhuma sessão iniciada.'}</div></div></div>`;
return top+status+base;};
decisionPage=function(c,p){const f=flow(p,c);return `${proceduralCard(c,p)}${f.pronuncia?`<div class="panel"><div class="eyebrow">JÚRI · FASE PRELIMINAR</div><h3>${es(f.pronuncia.result)}</h3><p>Pronúncia não é condenação. ${f.plenary?`Sessão de plenário prevista para dia ${f.hearingDate}.`:''}</p></div>`:''}${previous.decisionPage(c,p)}`;};
function guide(c,p){return `<div class="v3-grid"><section class="panel"><h2>Como conduzir este caso</h2><ol><li>Leia as versões do cliente e da outra parte.</li><li>Investigue documentos, distinguindo prova material de alegações.</li><li>Entrevista personagens; eles podem omitir informações e divergir.</li><li>Junte provas pertinentes, protocole a peça e acompanhe o andamento.</li><li>Responda ao contraditório no calendário fictício.</li><li>Compareça na data de audiência, formule pedidos e encerre a instrução.</li><li>Examine a fundamentação e avalie se há base para recurso.</li></ol><p class="mini">Seu cliente é o <b>assistido</b>. Isso não significa que seja necessariamente réu ou culpado.</p></section><section class="panel"><h2>Termos básicos</h2><dl><dt><b>Assistido</b></dt><dd>Cliente representado.</dd><dt><b>Autor / requerente</b></dt><dd>Quem formula o pedido em uma ação cível ou de família.</dd><dt><b>Réu / requerido</b></dt><dd>Quem responde à ação; no penal, acusado é quem responde à imputação criminal.</dd><dt><b>Contraditório</b></dt><dd>Oportunidade de conhecer e contestar elementos processuais.</dd><dt><b>Autos</b></dt><dd>Conjunto de documentos e atos registrados no processo.</dd><dt><b>Pronúncia</b></dt><dd>Decisão na primeira fase do Júri que não equivale a condenação.</dd><dt><b>Sentença</b></dt><dd>Decisão judicial que encerra uma fase cognitiva nos termos legais.</dd></dl></section></div><div class="panel"><h3>Base indicada para este caso</h3><p>${es(c.law)}</p><p>${es(c.legalNote)}</p><p class="mini">Referência pedagógica; nunca substitui consulta às leis vigentes nem orientação de profissional.</p></div>`;}
dossier=function(){let c=iCur(),p=pCur();if(!c||!p)return previous.dossier();const components={resumo:overview,provas:evidencePage,testemunhas:witnessesPage,entrevista:interviewsPage,custos:familyBudget,peticao:petitionPage,audiencia:hearingPage,autos:autosPage,decisao:decisionPage,andamentos:proceedings,guia:guide};return caseHeader(c,p)+(components[s.tab]||overview)(c,p)};
calendar=function(){const appointments=[];for(const c of CASES){let p=s.cases[c.id];if(!p)continue;let f=flow(p,c);for(const e of f.events.filter(e=>!e.done)){appointments.push({day:e.day,case:c,event:e});}}
appointments.sort((a,b)=>a.day-b.day);let due=appointments.filter(x=>x.day<=s.day+3).length;return `<div class="eyebrow">PJE FICTÍCIO · AGENDA PROFISSIONAL</div><h1>Calendário judicial</h1><p>Hoje: <b>${dateOf(s.day)}</b> · dia ${s.day} da carreira. ${due?`${due} movimentação(ões) nos próximos três dias.`:'Nenhuma movimentação nos próximos três dias.'}</p><div class="panel"><h3>Controle da passagem do tempo</h3><div class="v3-cta"><button class="btn primary" onclick="advanceTime(1)">+1 dia</button><button class="btn" onclick="advanceTime(7)">+7 dias</button><button class="btn" onclick="advanceTime(30)">+30 dias</button></div><p class="mini">Em cada avanço, atos agendados são processados em ordem, inclusive de outras causas do escritório. Avançar um mês pode fazer você perder o prazo didático de uma manifestação.</p></div><div class="panel"><h2>Pauta de intimações e audiências</h2>${appointments.length?appointments.slice(0,60).map(x=>`<div class="docentry"><div><b>${x.day<=s.day?'⚠ ':'◷ '}${dateOf(x.day)} · ${es(labels[x.event.type]||x.event.type)}</b><div class="mini">${es(x.case.client)} — ${es(x.case.title)} / ${es(x.case.number)}</div><p class="mini">${es(x.event.detail)}</p></div><button class="btn sm" onclick="selected('${x.case.id}','andamentos')">Abrir autos</button></div>`).join(''):'<p class="muted">Nenhum compromisso futuro. Aceite um cliente e protocole uma peça para gerar o calendário.</p>'}</div><div class="panel"><h3>Histórico do escritório</h3>${s.logs.slice(0,20).map(x=>`<div class="logentry"><b>Dia ${x.day}:</b> ${es(x.text)}</div>`).join('')||'Nenhum evento.'}</div>`;};
dashboard=function(){let base=previous.dashboard();let total=Object.values(s.cases).length;let up=[];for(const c of CASES){let p=s.cases[c.id];if(!p)continue;let f=flow(p,c),n=caseDue(f);if(n)up.push({c,f,n});}up.sort((a,b)=>a.n.day-b.n.day);
return `<div class="v3-worldhead"><span class="eyebrow">ESCRITÓRIO EM MOVIMENTO</span><h2>Um mundo jurídico que não para enquanto você atende outros clientes</h2><p>Hoje: <b>${dateOf(s.day)}</b> · dia ${s.day}. Os processos têm suas próprias agendas, manifestações e decisões.</p><div class="v3-cta"><button class="btn primary" onclick="nav('agenda')">Abrir calendário</button><button class="btn" onclick="advanceTime(7)">Avançar uma semana</button></div><div class="v3-worldstats"><div><strong>${total}</strong><small>Processos ativos ou concluídos</small></div><div><strong>${up.length}</strong><small>Atos previstos</small></div><div><strong>${up.filter(x=>x.n.day<=s.day+7).length}</strong><small>Próximos 7 dias</small></div></div>${up.slice(0,3).map(x=>`<div class="v3-urgent"><div><b>${dateOf(x.n.day)} · ${es(labels[x.n.type])}</b><p>${es(x.c.client)} — ${es(x.c.title)}</p></div><button class="btn sm" onclick="selected('${x.c.id}','andamentos')">Examinar</button></div>`).join('')}</div>${base}`;};
office=function(){return `<div class="panel"><div class="eyebrow">GESTÃO PROFISSIONAL</div><h3>Escritório que existe no calendário</h3><p>Ao completar cada 30 dias fictícios, o escritório paga despesas operacionais de R$ 3.000 + R$ 140 por caso não encerrado. Os casos e prazos continuam avançando mesmo enquanto você trabalha em outra área.</p><p class="mini">O sistema financeiro é uma mecânica ficcional, não previsão de honorários reais.</p></div>`+previous.office();};
// Pequeno tutorial na primeira visita não bloqueia navegação
let oldRender=render;
render=function(){oldRender();if(s.view==='dossie'){let p=pCur(),c=iCur();if(p&&c)flow(p,c);} };
// Migração sem apagar saves: garante fluxo em todas as causas já aceitas
for(const id of Object.keys(s.cases)){const c=get(id);if(c)flow(s.cases[id],c)}
window.__TRIBUNAL_SIM3__={flow,advanceTime:progressDays,legalEvaluation,kind,dateOf,publishDecision,scheduleEvent:evt};
refresh();
})();
